// AWI: sinkron unit ke semua kalkulator - sekali jalan (hapus setelah dipakai)
add_action('rest_api_init', function () {
	register_rest_route('awi/v1', '/calcfix', array(
		'methods' => 'POST',
		'permission_callback' => function () { return current_user_can('manage_options'); },
		'callback' => function () {
			global $wpdb;
			$t = $wpdb->prefix . 'snippets';
			$out = array();
			$rep = function ($c, $pairs, &$log) { foreach ($pairs as $a => $b) { $n = substr_count($c, $a); $log[] = $n . 'x ' . substr($a, 0, 50); if ($n) $c = str_replace($a, $b, $c); } return $c; };
			$ph = "o.placeholder=p?'':'Harga diumumkan saat peluncuran, isi perkiraan';";
			// 13 Kalkulator Simulasi Kredit
			$c = $wpdb->get_var("SELECT code FROM $t WHERE id=13"); $o = $c; $log = array();
			$c = $rep($c, array(
				"'BYD Atto 1':[['Standard',213000000],['Dynamic',224000000],['Premium',260000000]],\n  'BYD Atto 3'" => "'BYD Atto 1':[['Standard',213000000],['Dynamic',224000000],['Premium',260000000]],\n  'BYD Atto 2 (inden)':[['Dynamic',0],['Premium',0]],\n  'BYD Atto 3'",
				"['Cross Superior',393400000],['Cross Captain Seat',403400000]]," => "['Cross Superior 7 Seater',393400000],['Superior Captain Seat',403400000]],\n  'BYD TiTAN 7 DM (inden)':[['FWD DM-i',0],['AWD DM-p',0]],",
				"['Premium Extended 2026',884000000]" => "['Premium Ext 2026',884000000]",
				"['Premium Extended 2026',897000000]" => "['Premium Ext 2026',897000000]",
				"[['Advance',1118000000]]" => "[['Denza D9',1118000000]]",
				"[['Z9 GT',2288000000]]" => "[['Premium',2288000000]]",
				"function setOtr(){o.value=num(D[m.value][t.value][1]).toLocaleString('id-ID');calc();}" => "function setOtr(){var p=num(D[m.value][t.value][1]);o.value=p?p.toLocaleString('id-ID'):'';" . $ph . "calc();}",
			), $log);
			if ($c !== $o) $wpdb->update($t, array('code' => $c), array('id' => 13));
			$i = strpos($c, 'var tipe=D[m.value][t.value][0],insTx');
			$out['s13'] = array('log' => $log, 'tail' => $i === false ? null : substr($c, $i, 1600));
			// 24 Kalkulator Paket DP Rendah
			$c = $wpdb->get_var("SELECT code FROM $t WHERE id=24"); $o = $c; $log = array();
			$c = $rep($c, array(
				"['Superior Captain Seat',403400000]],\n 'BYD M6'" => "['Superior Captain Seat',403400000]],\n 'BYD TiTAN 7 DM (inden)':[['FWD DM-i',0],['AWD DM-p',0]],\n 'BYD M6'",
				"'BYD Atto 1':[['Standard',213000000],['Dynamic',224000000],['Premium',260000000]],\n 'BYD M6 DM'" => "'BYD Atto 1':[['Standard',213000000],['Dynamic',224000000],['Premium',260000000]],\n 'BYD Atto 2 (inden)':[['Dynamic',0],['Premium',0]],\n 'BYD M6 DM'",
				"function setOtr(){o.value=D[m.value][t.value][1].toLocaleString('id-ID');run();}" => "function setOtr(){var p=D[m.value][t.value][1];o.value=p?p.toLocaleString('id-ID'):'';" . $ph . "run();}",
				"msg.textContent='Untuk '+m.value+' paket DP rendah dihitung khusus sesuai pengajuan. Klik tombol di bawah, AWI kirim hitungannya lewat WhatsApp.';" => "msg.textContent=otr?'Untuk '+m.value+' paket DP rendah dihitung khusus sesuai pengajuan. Klik tombol di bawah, AWI kirim hitungannya lewat WhatsApp.':'Harga resmi '+m.value.replace(' (inden)','')+' diumumkan saat peluncuran. Klik tombol di bawah untuk masuk daftar inden, AWI kirim simulasi DP rendah begitu harga keluar.';",
				"txt='Halo Kak AWI, saya mau hitungan paket DP rendah untuk '+m.value+' '+tipe+' (OTR '+rp(otr)+').';" => "txt=otr?'Halo Kak AWI, saya mau hitungan paket DP rendah untuk '+m.value+' '+tipe+' (OTR '+rp(otr)+').':'Halo Kak AWI, saya mau inden '+m.value.replace(' (inden)','')+' '+tipe+'. Tolong kirim simulasi DP rendah begitu harga resmi keluar.';",
			), $log);
			if ($c !== $o) $wpdb->update($t, array('code' => $c), array('id' => 24));
			$out['s24'] = $log;
			// 10303 Kalkulator Charging
			$c = get_post_field('post_content', 10303); $o = $c; $log = array();
			$tn = "'Angka ini jangkauan listrik murni (NEDC), belum termasuk tangki bensin 60 L. Harga & spesifikasi Indonesia final mengikuti peluncuran.'";
			$c = $rep($c, array(
				"'Seal': {'Premium Ext 2026'" => "'TiTAN 7 DM (PHEV, inden)': {'FWD DM-i': {'b': 26.6, 'r': 110, 'dc': 54, 'ac': 6.6, 'v': 1, 'n': " . $tn . "}, 'AWD DM-p': {'b': 35.6, 'r': 155, 'dc': 73, 'ac': 6.6, 'v': 1, 'n': " . $tn . "}}, 'Seal': {'Premium Ext 2026'",
			), $log);
			if ($c !== $o) { $wpdb->update($wpdb->posts, array('post_content' => $c), array('ID' => 10303)); clean_post_cache(10303); }
			$out['p10303'] = $log;
			$bs = chr(92);
			if (function_exists('Code_Snippets' . $bs . 'clean_snippets_cache')) call_user_func('Code_Snippets' . $bs . 'clean_snippets_cache', $t);
			wp_cache_flush();
			return $out;
		},
	));
});
